"""Cold-feed stoichiometry and explicitly conditional phase/IR requirements."""
from pathlib import Path
import json,math,hashlib
P=Path(__file__).resolve().parent
# Per incoming15N nucleus: .375 N2H4 + .125 N2 hasH/N=1.5.
xh=.375;xn=.125;mass_h=xh*34;mass_n=xn*30;total=mass_h+mass_n
assert math.isclose((xh*4)/(2*xh+2*xn),1.5)
wH=mass_h/total;wN=mass_n/total
sigma=5.670374419e-8;R=1.1e9;v=2.4e6;rho=1000.;a=.01;alpha=.02182
blackdose=3*sigma*1000**4*R/(rho*a*v);dose=alpha*blackdose
out={'scope':__doc__,'H_per_N':1.5,'isotope':'15N/protium','per_catalyst_N_atom':{'N2H4_molecules':xh,'N2_molecules':xn,'H_atoms':xh*4,'N_atoms':2*xh+2*xn},'payload_mass_fraction':{'hydrazine':wH,'nitrogen':wN},'alternative_NH3_N2_payload_mass_fraction':{'ammonia':9/16.5,'nitrogen':7.5/16.5},'cold_state_scope':'Selected physical candidates are a50K sealed heterogeneous solid composite or separately conditioned hydrazine/N2 populations. The computational FEOSrho1000,T250 reference is a homogenized contact surrogate, not a claim of condensedN2at250K. Actual mixture density, void fraction, molecularEOS, interface mixing and capsule stresses remain requirements.','bulk_density_target_kg_m3':1000,'density_example':{'hydrazine_reference_kg_m3':1062.5,'nitrogen_reference_kg_m3':1000,'additive_volume_mixture_kg_m3':1/(wH/1062.5+wN/1000),'scope':'Illustrative density choices, not measured15N composite data. Cryocrystal experiments show comparable molar-volume scales under specified containment pressure.'},'IR_reference':{'radius_m':R,'speed_m_s':v,'grain_radius_m':a,'density_kg_m3':rho,'cavity_K':1000,'Planck_absorptivity':alpha,'flight_s':R/v,'absorbed_J_kg':dose,'conditional_N2_heat_allowance_J_kg':30000,'max_absorptivity_for_allowance':30000/blackdose,'max_free_path_m_at_reference_absorptivity':R*30000/dose,'grain_radius_m_for_full_path':a*dose/30000,'scope':'Reuse radiation-interface smoothAl absorptivity reference.30kJ/kg is a chosen small-temperature-change budget, not a measured loss-of-function point. Capsule pressure/headspace may permit greater warming, with geometry/scattering consequences.'},'chemical_energy_scale':{'hydrazine_formation_J_mol':50370,'decomposition_to_N2_H2_J_kg_mixture':wH*50370/.034,'comparison_contact_q_J_kg':113862490149.77106,'fraction_contact_heat':wH*50370/.034/113862490149.77106,'scope':'Thermochemical scale for one product convention. Small energy fraction does not establish stability or prevent fragmentation during flight.'},'sources':[{'title':'NASA hydrazine/ammonia property table','url':'https://ntrs.nasa.gov/api/citations/20120003055/downloads/20120003055.pdf','use':'Natural hydrazine melting274.63K, liquid density1.004g/mL at298K, heat of formation50.37kJ/mol.'},{'title':'NIST nitrogen phase change data','url':'https://webbook.nist.gov/cgi/cbook.cgi?ID=C7727379&Mask=4','use':'Triplepoint63.14K, boiling77.34K, critical126.19K. CondensedN2requires a cryogenic or compressed-state design.'},{'title':'Konstantinov etal2005 nitrogen measurements','url':'https://nasplib.isofts.kiev.ua/bitstreams/6dfa3e52-8cf2-48d1-9002-389dd9cdc4cc/download','use':'Confined solid samples20Kto melting; molar volumes27.36–28.76cm3/mol. Not a zero-pressure15N density measurement.'}],'code_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
(P/'recipe-screen.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
